243	                    <p className="text-xs text-gray-400 dark:text-zinc-500 mt-0.5 truncate">{tipo.icon_name}</p>
244	                  </div>
245	                  <div className="flex gap-1 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity self-end sm:self-auto">
246	                    <button
247	                      onClick={() => setModal(tipo)}
248	                      className="p-1.5 sm:p-2 text-gray-400 dark:text-zinc-500 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/40 rounded-lg transition-colors"
249	                      title="Editar"
250	                    >
251	                      <Icon name="Pencil" size={15} />
252	                    </button>
253	                    <button
254	                      onClick={() => handleRemover(tipo)}
255	                      disabled={removendo === tipo.id}
256	                      className="p-1.5 sm:p-2 text-gray-400 dark:text-zinc-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40 rounded-lg transition-colors disabled:opacity-40"
257	                      title="Remover"
258	                    >
259	                      <Icon name="Trash2" size={15} />
260	                    </button>
261	                  </div>
262	                </motion.div>
263	              ))}
264	            </AnimatePresence>
265	          </div>
266	        )}
267	      </main>
268	
269	      {modal && (
270	        <Modal
271	          tipo={modal === 'novo' ? null : modal}
272	          tiposExistentes={tipos}
273	          onClose={() => setModal(null)}
274	          onSave={() => { setModal(null); carregar(); }}
275	        />
276	      )}
277	    </div>
278	  );
279	};
280	
281	export default AdminTiposEstabelecimento;
