import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { getTiposEstabelecimento, criarTipoEstabelecimento, atualizarTipoEstabelecimento, removerTipoEstabelecimento } from '../../services/adminService';
import Icon from '../../components/AppIcon';
import AdminHeader from '../../components/admin/AdminHeader';

/* ── Ícones disponíveis para tipos de estabelecimento ───────────── */
const ICONES = [
  'Store', 'UtensilsCrossed', 'Pill', 'HardHat', 'ShoppingBag', 'ShoppingCart', 'Shirt',
  'Flower2', 'Fuel', 'Wine', 'Coffee', 'Cake', 'Scissors', 'Wrench', 'PawPrint', 'BookOpen',
  'Smartphone', 'Gift', 'Package', 'Truck', 'Building2', 'Tag',
];


/* ── Normaliza nome pra comparar sem acento/maiúscula ───────────── */
const normalizarNome = (s) =>
  (s ?? '').normalize('NFD').replace(/\p{Diacritic}/gu, '').trim().toLowerCase();

/* ── Modal criar/editar tipo ─────────────────────────────────────── */
const EMPTY = { name: '', icon_name: 'Store' };

const Modal = ({ tipo, tiposExistentes, onClose, onSave }) => {
  const [form, setForm] = useState(
    tipo ? { name: tipo.name, icon_name: tipo.icon_name } : { ...EMPTY }
  );
  const [salvando, setSalvando] = useState(false);
  const [erro, setErro] = useState(null);
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name.trim()) return;

    const nomeNormalizado = normalizarNome(form.name);
    const duplicado = (tiposExistentes ?? []).find(
      (t) => t.id !== tipo?.id && normalizarNome(t.name) === nomeNormalizado
    );
    if (duplicado) {
      setErro(`Já existe um tipo chamado "${duplicado.name}"`);
      return;
    }

    setSalvando(true);
    setErro(null);
    try {
      if (tipo) {
        await atualizarTipoEstabelecimento(tipo.id, form);
      } else {
        await criarTipoEstabelecimento(form);
      }
      onSave();
    } catch (err) {
      setErro(err.message);
    } finally {
      setSalvando(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4" onClick={onClose}>
      <div className="bg-white dark:bg-zinc-800 rounded-2xl w-full max-w-lg p-6 max-h-[90vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
        <h3 className="text-lg font-bold text-gray-900 dark:text-zinc-100 mb-5">
          {tipo ? 'Editar Tipo de Estabelecimento' : 'Novo Tipo de Estabelecimento'}
        </h3>

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* Preview */}
          <div className="flex items-center gap-4 p-4 bg-gray-50 dark:bg-zinc-900 rounded-xl">
            <div className="w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-md bg-blue-600">
              <Icon name={form.icon_name} size={24} />
            </div>
            <div>
              <p className="font-bold text-gray-900 dark:text-zinc-100">{form.name || 'Nome do tipo'}</p>
              <p className="text-xs text-gray-400 dark:text-zinc-500 mt-0.5">{form.icon_name}</p>
            </div>
          </div>

          {/* Nome */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 dark:text-zinc-300 mb-1">Nome *</label>
            <input
              required
              value={form.name}
              onChange={(e) => set('name', e.target.value)}
              className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-800 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="Ex: Farmácia"
            />
          </div>

          {/* Seletor de ícone */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 dark:text-zinc-300 mb-2">Ícone</label>
            <div className="grid grid-cols-8 gap-1.5 p-3 bg-gray-50 dark:bg-zinc-900 rounded-xl max-h-48 overflow-y-auto">
              {ICONES.map((icon) => (
                <button
                  key={icon}
                  type="button"
                  title={icon}
                  onClick={() => set('icon_name', icon)}
                  className={`w-9 h-9 rounded-lg flex items-center justify-center transition-all ${
                    form.icon_name === icon
                      ? 'bg-blue-600 text-white shadow-md scale-110'
                      : 'text-gray-500 dark:text-zinc-400 hover:bg-gray-200 dark:hover:bg-zinc-700'
                  }`}
                >
                  <Icon name={icon} size={16} />
                </button>
              ))}
            </div>
            <div className="mt-2">
              <input
                value={form.icon_name}
                onChange={(e) => set('icon_name', e.target.value)}
                className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-800 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Ou digite o nome exato do ícone (ex: Store)"
              />
              <p className="text-xs text-gray-400 dark:text-zinc-500 mt-1">
                Não achou o ícone que quer? Busque o nome em{' '}
                <a href="https://lucide.dev/icons" target="_blank" rel="noreferrer" className="text-blue-600 underline">
                  lucide.dev/icons
                </a>{' '}
                e digite aqui o nome do ícone (aceita qualquer formato, ex: <code>shopping-basket</code> ou <code>ShoppingBasket</code>).
              </p>
            </div>
          </div>

          {erro && <p className="text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 rounded-lg px-3 py-2">{erro}</p>}

          <div className="flex gap-3 pt-1">
            <button type="button" onClick={onClose}
              className="flex-1 py-2.5 border border-gray-300 dark:border-zinc-700 rounded-xl text-sm text-gray-700 dark:text-zinc-300 hover:bg-gray-50 dark:hover:bg-zinc-700/40">
              Cancelar
            </button>
            <button type="submit" disabled={salvando}
              className="flex-1 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-semibold hover:bg-blue-700 disabled:opacity-50">
              {salvando ? 'Salvando...' : 'Salvar'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

/* ── Componente principal ────────────────────────────────────────── */
const AdminTiposEstabelecimento = () => {
  const [tipos, setTipos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [erro, setErro] = useState(null);
  const [modal, setModal] = useState(null); // null | 'novo' | tipo_obj
  const [removendo, setRemovendo] = useState(null);
  const [busca, setBusca] = useState('');

  const tiposFiltrados = tipos.filter((t) =>
    normalizarNome(t.name).includes(normalizarNome(busca))
  );

  const carregar = useCallback(() => {
    setLoading(true);
    getTiposEstabelecimento()
      .then((d) => setTipos(d.tipos ?? []))
      .catch((e) => setErro(e.message))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { carregar(); }, [carregar]);

  const handleRemover = async (tipo) => {
    if (!window.confirm(`Remover "${tipo.name}"? Estabelecimentos vinculados perderão o tipo.`)) return;
    setRemovendo(tipo.id);
    try {
      await removerTipoEstabelecimento(tipo.id);
      setTipos((prev) => prev.filter((t) => t.id !== tipo.id));
    } catch (e) {
      alert(e.message);
    } finally {
      setRemovendo(null);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-zinc-900">
      <AdminHeader active="/admin/tipos-estabelecimento" title="Tipos de Estabelecimento" subtitle="Restaurante, farmácia, material de construção..." />

      <main className="p-4 sm:p-6 max-w-5xl mx-auto">
        <div className="flex items-center justify-between mb-4 gap-3">
          <p className="text-sm text-gray-500 dark:text-zinc-400 whitespace-nowrap">{tipos.length} tipo(s)</p>
          <button
            onClick={() => setModal('novo')}
            className="px-3 sm:px-4 py-2 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700 flex items-center gap-2 flex-shrink-0"
          >
            <Icon name="Plus" size={16} /> <span className="hidden sm:inline">Novo Tipo</span><span className="sm:hidden">Novo</span>
          </button>
        </div>

        <div className="relative mb-6">
          <Icon name="Search" size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 dark:text-zinc-500" />
          <input
            value={busca}
            onChange={(e) => setBusca(e.target.value)}
            placeholder="Buscar tipo já cadastrado..."
            className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-800 text-gray-900 dark:text-zinc-100 rounded-xl pl-9 pr-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        {erro && <p className="text-red-600 dark:text-red-400 text-sm mb-4 bg-red-50 dark:bg-red-950/30 rounded-lg px-4 py-3">{erro}</p>}

        {loading ? (
          <div className="flex justify-center py-16">
            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
          </div>
        ) : tipos.length === 0 ? (
          <div className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-200 dark:border-zinc-700 p-14 text-center">
            <Icon name="Store" size={44} className="text-gray-200 dark:text-zinc-600 mx-auto mb-3" />
            <p className="text-gray-400 dark:text-zinc-500 mb-4">Nenhum tipo cadastrado</p>
            <button onClick={() => setModal('novo')}
              className="px-5 py-2.5 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700">
              Criar primeiro tipo
            </button>
          </div>
        ) : tiposFiltrados.length === 0 ? (
          <div className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-200 dark:border-zinc-700 p-10 text-center">
            <Icon name="SearchX" size={36} className="text-gray-200 dark:text-zinc-600 mx-auto mb-3" />
            <p className="text-gray-400 dark:text-zinc-500">Nenhum tipo encontrado para "{busca}"</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 gap-2.5 sm:gap-4">
            <AnimatePresence>
              {tiposFiltrados.map((tipo) => (
                <motion.div
                  key={tipo.id}
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.9 }}
                  className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-100 dark:border-zinc-700 p-3 sm:p-5 flex flex-col sm:flex-row items-start sm:items-center gap-2 sm:gap-4 group hover:shadow-md transition-shadow"
                >
                  <div className="w-10 h-10 sm:w-14 sm:h-14 rounded-xl sm:rounded-2xl flex items-center justify-center text-white shadow-md flex-shrink-0 bg-blue-600">
                    <Icon name={tipo.icon_name ?? 'Store'} size={18} className="sm:hidden" />
                    <Icon name={tipo.icon_name ?? 'Store'} size={24} className="hidden sm:block" />
                  </div>
                  <div className="flex-1 min-w-0 w-full">
                    <p className="font-bold text-gray-900 dark:text-zinc-100 text-sm sm:text-base truncate">{tipo.name}</p>
                    <p className="text-xs text-gray-400 dark:text-zinc-500 mt-0.5 truncate">{tipo.icon_name}</p>
                  </div>
                  <div className="flex gap-1 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity self-end sm:self-auto">
                    <button
                      onClick={() => setModal(tipo)}
                      className="p-1.5 sm:p-2 text-gray-400 dark:text-zinc-500 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-950/40 rounded-lg transition-colors"
                      title="Editar"
                    >
                      <Icon name="Pencil" size={15} />
                    </button>
                    <button
                      onClick={() => handleRemover(tipo)}
                      disabled={removendo === tipo.id}
                      className="p-1.5 sm:p-2 text-gray-400 dark:text-zinc-500 hover:text-red-600 dark:hover:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40 rounded-lg transition-colors disabled:opacity-40"
                      title="Remover"
                    >
                      <Icon name="Trash2" size={15} />
                    </button>
                  </div>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        )}
      </main>

      {modal && (
        <Modal
          tipo={modal === 'novo' ? null : modal}
          tiposExistentes={tipos}
          onClose={() => setModal(null)}
          onSave={() => { setModal(null); carregar(); }}
        />
      )}
    </div>
  );
};

export default AdminTiposEstabelecimento;

