import { BadRequestException, ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { SupabaseService } from '../supabase/supabase.service';
import { normalizarDominio, validarFormatoDominio, isDominioReservado } from '../common/dominio.util';
import { CategoriasService } from '../categorias/categorias.service';
import { ProdutosService } from '../produtos/produtos.service';
import { PedidosService } from '../pedidos/pedidos.service';
import { GeocodingService } from '../motoboy/geocoding.service';
import { MotoboyService } from '../motoboy/motoboy.service';
import { EstoqueService } from '../estoque/estoque.service';
import { CombosService } from '../combos/combos.service';
import { PlanosService } from '../planos/planos.service';
import { RedisService } from '../redis/redis.service';

const TTL_MINHA_EMPRESA = 15;

@Injectable()
export class RestauranteService {
  constructor(
    private supabase: SupabaseService,
    private categorias: CategoriasService,
    private produtos: ProdutosService,
    private pedidos: PedidosService,
    private geocoding: GeocodingService,
    private motoboyService: MotoboyService,
    private estoque: EstoqueService,
    private combosService: CombosService,
    private planos: PlanosService,
    private redis: RedisService,
  ) {}

  // Cacheada porque o header do painel (menu lateral) monta 3 hooks que bateriam
  // nessa rota em paralelo — cache-aside curto evita repetir as 3 queries a cada
  // navegação entre páginas de /restaurante/*. Mesmo padrão do catálogo público
  // (ver CatalogoController): sem invalidação manual, defasagem curta é aceitável.
  async minhaEmpresa(userId: string) {
    const cacheKey = `restaurante:minha-empresa:${userId}`;
    const cached = await this.redis.getJSON<any>(cacheKey);
    if (cached) return cached;

    const resultado = await this.buscarMinhaEmpresa(userId);
    await this.redis.setJSON(cacheKey, resultado, TTL_MINHA_EMPRESA);
    return resultado;
  }

  private async buscarMinhaEmpresa(userId: string) {
    // payment_config nunca sai daqui em claro — tem rota própria mascarada
    // (GET /restaurante/config, ver getConfig() nesta mesma classe).
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .select('id, name, address, state, city, neighborhood, cep, lat, lng, lat_ajustado_manualmente, logo_url, slug, custom_domain, custom_domain_status, custom_domain_motivo_recusa, business_hours, comissao_pct, type_id, modulo_delivery, modulo_salao, modulo_gdoor, auto_atendimento_habilitado, whatsapp, created_at')
      .eq('user_id', userId)
      .maybeSingle();

    if (error) throw error;
    if (!data) throw new NotFoundException('Nenhum restaurante vinculado');

    const { data: tipoRestaurante } = await this.supabase.client
      .from('establishment_types')
      .select('id')
      .eq('name', 'Restaurante')

-- Tipos de estabelecimento (restaurante, farmácia, mat. construção etc).
-- Populada pelo dev via migration — sem CRUD de admin nessa fase.
CREATE TABLE IF NOT EXISTS public.establishment_types (
    id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name       TEXT NOT NULL UNIQUE,
    icon_name  TEXT NOT NULL DEFAULT 'Store',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

INSERT INTO public.establishment_types (name, icon_name)
VALUES
    ('Restaurante',          'UtensilsCrossed'),
    ('Farmácia',             'Pill'),
    ('Material de Construção', 'HardHat')
ON CONFLICT (name) DO NOTHING;

ALTER TABLE public.establishment_types ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'public' AND tablename = 'establishment_types'
          AND policyname = 'establishment_types_public_read'
    ) THEN
        EXECUTE 'CREATE POLICY "establishment_types_public_read" ON public.establishment_types FOR SELECT USING (true)';
    END IF;
END $$;

-- Vincula cada restaurante a um tipo. Default = "Restaurante", pra não quebrar cadastros existentes.
ALTER TABLE public.restaurants
    ADD COLUMN IF NOT EXISTS type_id BIGINT REFERENCES public.establishment_types(id);

UPDATE public.restaurants
SET type_id = (SELECT id FROM public.establishment_types WHERE name = 'Restaurante')
WHERE type_id IS NULL;

