import { Injectable, NotFoundException } from '@nestjs/common';
import { SupabaseService } from '../supabase/supabase.service';
import { UsuariosService } from '../usuarios/usuarios.service';

@Injectable()
export class EmpresasService {
  constructor(
    private supabase: SupabaseService,
    private usuarios: UsuariosService,
  ) {}

  private gerarSlug(name: string): string {
    return name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
  }

  async listar(apenasAtivo?: boolean) {
    let query = this.supabase.client
      .from('restaurants')
      .select('id, name, address, logo_url, comissao_pct, user_id, slug, bloqueado, custom_domain, custom_domain_status, custom_domain_solicitado_em, custom_domain_motivo_recusa, modulo_delivery, modulo_salao, modulo_gdoor, created_at')
      .order('name');

    const { data, error } = await query;
    if (error) throw error;
    return { empresas: data, total: data?.length ?? 0 };
  }

  async buscar(id: number) {
    // payment_config nunca sai daqui em claro — tem rota própria mascarada
    // (GET /empresas/:id/config, ver empresas.controller.ts).
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .select('id, name, address, logo_url, business_hours, comissao_pct, user_id, slug, modulo_delivery, modulo_salao, modulo_gdoor, created_at')
      .eq('id', id)
      .maybeSingle();

    if (error) throw error;
    if (!data) throw new NotFoundException(`Empresa ${id} não encontrada`);

    const [{ data: metricas }, { data: platData }] = await Promise.all([
      this.supabase.client.from('orders').select('id, total, status').eq('restaurant_id', id),
      this.supabase.client.from('platform_settings').select('config').eq('id', 1).maybeSingle(),
    ]);

    const entregues = (metricas ?? []).filter((p) => p.status === 'delivered');
    const faturamento = entregues.reduce((acc, p) => acc + (p.total ?? 0), 0);
    const platCfg = (platData?.config ?? {}) as Record<string, any>;
    const comissaoPct = data.comissao_pct ?? platCfg.comissao_padrao_pct ?? 5;

    return {
      empresa: data,
      metricas: {
        total_pedidos: metricas?.length ?? 0,
        pedidos_entregues: entregues.length,
        faturamento,
        comissao_acumulada: parseFloat((faturamento * (comissaoPct / 100)).toFixed(2)),
      },
    };
  }

  async criar(body: {
    name: string;
    address?: string;
    logo_url?: string;
    comissao_pct?: number;
    user_id?: string;
    slug?: string;
    modulo_delivery?: boolean;
    modulo_salao?: boolean;
    modulo_gdoor?: boolean;
  }) {
    const { data, error } = await this.supabase.client
      .from('restaurants')
      .insert({
        name: body.name,
        address: body.address ?? null,
        logo_url: body.logo_url ?? null,
        comissao_pct: body.comissao_pct ?? null,
        user_id: body.user_id || null,
        slug: body.slug || this.gerarSlug(body.name),
        modulo_delivery: body.modulo_delivery ?? true,
        modulo_salao: body.modulo_salao ?? false,
        modulo_gdoor: body.modulo_gdoor ?? false,
      })
      .select()
      .single();

    if (error) throw error;
    return data;
  }

  async atualizar(id: number, body: Partial<{
    name: string;
    address: string;
    logo_url: string;
    comissao_pct: number;
    business_hours: object;
    payment_config: object;
    user_id: string;
    modulo_delivery: boolean;
    modulo_salao: boolean;
    modulo_gdoor: boolean;
  }>) {
    // Delega ao serviço central pra manter user_profiles.role sincronizado
    // com o vínculo — editar só restaurants.user_id aqui deixava o dono sem
    // acesso ao painel mesmo com o vínculo "correto" no banco.
    if ('user_id' in body) {
      await this.usuarios.sincronizarVinculoDono(id, body.user_id || null);
    }

    // body vem de @Body() body: any no controller — nunca repassar cru pro
    // .update() (mesmo padrão de fix já usado em B2/B7/B10).
    const payload: Record<string, any> = { updated_at: new Date().toISOString() };
    if (body.name !== undefined) payload.name = body.name;
    if (body.address !== undefined) payload.address = body.address;
    if (body.logo_url !== undefined) payload.logo_url = body.logo_url;
    if (body.comissao_pct !== undefined) payload.comissao_pct = body.comissao_pct;
    if (body.business_hours !== undefined) payload.business_hours = body.business_hours;
    if (body.payment_config !== undefined) payload.payment_config = body.payment_config;
    if (body.modulo_delivery !== undefined) payload.modulo_delivery = body.modulo_delivery;
    if (body.modulo_salao !== undefined) payload.modulo_salao = body.modulo_salao;
    if (body.modulo_gdoor !== undefined) payload.modulo_gdoor = body.modulo_gdoor;

    const { data, error } = await this.supabase.client
      .from('restaurants')
      .update(payload)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

